source:
(()=>{
/* Bài 1 — Nhập môn C++: cấu trúc chương trình và xuất dữ liệu (viết lại theo chuẩn tường minh, 19/10/2026)
   Bối cảnh: quầy trà sữa của lớp tại Lễ hội Mùa Xuân. Tiết 1 = Chặng 1, tiết 2 = Chặng 2, cuối tiết 2 = Chặng chứng chỉ.
   Mỗi chặng 6 tab (VAN_PHONG.md): Bối cảnh → Đoán rồi chạy → Kiểm chứng/Kiểm lỗi → Ghi nhớ → Luyện tập → Phản tư.
   Chuẩn câu hỏi: có tình huống, hỏi một ý, 4 phương án; mỗi phương án sai là một cách hiểu sai thường gặp và có lời giải thích.
*/
"use strict";

const { scratch } = window.KIT;
const esc = window.KIT.esc;
const strip = code => window.CPP.stripComments(code);

/* ---------- đoạn code dùng xuyên suốt ---------- */
const CHAO_1 = `#include <iostream>
using namespace std;
int main() {
    cout << "Chao mung den quay tra sua!";
    cout << "Moi ban chon mon.";
    return 0;
}`;
const CHAO_2 = `#include <iostream>
using namespace std;
int main() {
    cout << "Chao mung den quay tra sua!" << endl;
    cout << "Moi ban chon mon.";
    return 0;
}`;
const MAN_CHAO = ["Chao mung den quay tra sua!\nMoi ban chon mon.", "Chao mung den quay tra sua!Moi ban chon mon.",
  "Chao mung den quay tra sua! Moi ban chon mon.", "\"Chao mung den quay tra sua!\"\n\"Moi ban chon mon.\""];

const MENU_LOI = `#include <iostream>
using namespace std;
int main() {
    cout << "MENU QUAY TRA SUA";
    cout << "Tra sua tran chau";
    cout << "Tra dao";
    return 0;
}`;

const NAM_LOI = `#include <iostream>
using namespace std;
int main() {
    cout << "BANG GIA" << endl;
    Cout << "Tra dao: 20000 dong" << endl;
    cout << "Tra sua: 25000 dong" << endl
    return 0;
}`;

const GIA_SO = `#include <iostream>
using namespace std;
int main() {
    cout << "Tra sua: " << 25000 << " dong" << endl;
    cout << "Combo 2 ly: " << 2 * 25000 << " dong";
    return 0;
}`;
const MAN_GIA = ["Tra sua: 25000 dong\nCombo 2 ly: 50000 dong", "Tra sua: 25000 dong\nCombo 2 ly: 2 * 25000 dong",
  "Tra sua:25000dong\nCombo 2 ly:50000dong", "Tra sua: 25000 dong Combo 2 ly: 50000 dong"];

const KHUNG_TRONG = `#include <iostream>
using namespace std;
int main() {
    // Viet cac lenh cout o day

    return 0;
}`;

/* ---------- khối trình bày dùng chung ---------- */
const boiCanh = (big, text) => `<div class="scene-card"><div class="scene-big">${big}</div>${text}</div>`;
const bang = (tieuDe, cot, dong) => `<div class="ky-title">${tieuDe}</div><table class="ky-table"><tr>${cot.map(c => `<th>${c}</th>`).join("")}</tr>
  ${dong.map(r => `<tr>${r.map(c => `<td>${c}</td>`).join("")}</tr>`).join("")}</table>`;
const timThem = links => `<div class="ky-title">Tìm hiểu thêm <small style="font-weight:600;color:var(--muted)">(không bắt buộc, mở ở tab mới)</small></div>
  <div class="tim-them">${links.map(([u, t]) => `<a href="${u}" target="_blank" rel="noopener">${t} ↗</a>`).join("")}</div>`;
const sauTab = kiem => `<div class="mission-row" style="grid-template-columns:repeat(auto-fit,minmax(96px,1fr))">
  ${["Bối cảnh", "Đoán rồi chạy", kiem, "Ghi nhớ", "Luyện tập", "Phản tư"].map((t, i) => `<div>${i + 1}<small>${t}</small></div>`).join("")}</div>`;
const bonBuoc = `<ol class="think-steps">
  <li><strong>Hiểu đề:</strong> chương trình cần in ra những dòng nào, theo thứ tự nào?</li>
  <li><strong>Chọn biến:</strong> bài này chưa cần biến vì không lưu dữ liệu nào.</li>
  <li><strong>Viết màn hình mong đợi trước:</strong> chép ra giấy từng dòng màn hình phải hiện.</li>
  <li><strong>Viết, chạy, so sánh, sửa:</strong> chạy chương trình, so từng chữ, từng dấu cách với màn hình mong đợi rồi sửa chỗ khác.</li></ol>`;
// Ghi nhớ: khung "Ghi vào vở" (đúng 3 ý, trùng slide chốt) + một lưu ý nhỏ; các bảng bên dưới chỉ để đọc, không chép.
const ghiVo = y => `<div class="ghi-vo"><div class="ghi-vo-tieu">📒 Ghi vào vở</div>
  <ol>${y.map(t => `<li>${t}</li>`).join("")}</ol></div>`;
const luuY = t => `<div class="luu-y"><b class="nhan">⚠ Lưu ý:</b> ${t}</div>`;
const chiTiet = `<p style="margin:18px 0 4px;color:var(--muted)">Các bảng dưới đây giải thích chi tiết hơn, dùng để đọc hiểu và tra lại khi làm bài. <strong>Không cần chép.</strong></p>`;
const manHinh = (tieuDe, text) => `<div class="screen-card" style="margin:10px 0"><div class="screen-head">🖥 ${tieuDe}</div><pre>${esc(text)}</pre></div>`;
const tuCham = "Với mỗi câu dưới đây, chọn mức đúng với bạn lúc này. Thầy dùng kết quả để biết cần giảng lại phần nào cho cả lớp.";
const huongDanDoan = n => `<p>Bạn sẽ gặp ${n} chương trình ngắn. Với mỗi chương trình, làm hai bước:</p>
  <ol><li><strong>Đoán:</strong> đọc code ở khung bên trái, rồi chọn màn hình bạn nghĩ máy sẽ in ra. Bấm <strong>Chốt dự đoán</strong>.</li>
  <li><strong>Chạy để kiểm tra:</strong> bấm <strong>▶ Chạy từng dòng</strong>. Mỗi lần bấm, máy thực hiện một câu lệnh: dòng đang chạy có mũi tên màu cam, chữ in ra hiện dần ở khung Màn hình, và phần giải thích cho biết máy vừa làm gì.</li></ol>
  <p>Đoán sai không bị trừ điểm. Chạy xong, bạn sẽ thấy vì sao mình đoán đúng hoặc sai. Làm xong lần này mới mở được lần sau.</p>`;

window.LESSON = {
  id: "bai01",
  chuan: 2,          // chuẩn câu hỏi 19/10: 4 phương án, phương án sai có giải thích, mỗi bước chạy có giải thích
  number: 1,
  title: "Nhập môn C++",
  story: "Quầy trà sữa Lễ hội Mùa Xuân",
  badge: { icon: "🧋", name: "Người dạy Bit nói" },
  skills: ["Cấu trúc chương trình C++", "Câu lệnh cout", "endl xuống dòng", "Chuỗi và số", "Đọc lỗi cú pháp", "Chú thích //"],
  certNote: "Nộp kèm: ảnh bài làm nhóm và bài cá nhân trên Programiz",

  errorTable: [
    ["Máy báo không biết tên “cout”", "Thiếu dòng <code>using namespace std;</code>", "Thêm <code>using namespace std;</code> ngay sau <code>#include &lt;iostream&gt;</code>"],
    ["Máy báo lỗi cú pháp ở khoảng dòng N", "Thường do thiếu dấu <code>;</code> ở cuối câu lệnh <em>ngay phía trên</em> dòng N, hoặc thiếu dấu <code>\"</code>, thiếu ngoặc <code>}</code>", "Xem dòng N và dòng ngay trên nó; thêm dấu còn thiếu"],
    ["Máy báo không biết tên “Cout” hoặc “Endl”", "C++ phân biệt chữ hoa và chữ thường", "Viết <code>cout</code>, <code>endl</code> bằng chữ thường"],
    ["Các dòng chữ bị dính liền nhau", "<code>cout</code> không tự xuống dòng", "Thêm <code>&lt;&lt; endl</code> ở cuối câu lệnh in dòng phía trên"],
    ["Thiếu hoặc thừa dấu cách giữa các chữ", "Máy chỉ in dấu cách nằm <em>bên trong</em> dấu ngoặc kép", "Thêm hoặc bớt dấu cách bên trong cặp <code>\" \"</code>"],
    ["Màn hình in ra phép tính thay vì kết quả", "Phép tính bị đặt trong dấu ngoặc kép nên máy coi là chuỗi", "Đặt phép tính ra ngoài dấu ngoặc kép, nối bằng <code>&lt;&lt;</code>"]
  ],

  steps: [
    /* ================= CHẶNG 1 · TIẾT 1 ================= */
    {
      kind: "stage", id: "stage-1", number: 1, nav: "Chặng 1",
      kicker: "CHẶNG 1 · TIẾT 1 · CẤU TRÚC CHƯƠNG TRÌNH VÀ LỆNH cout",
      title: "In lời chào và menu",
      bit: "Chào bạn! Chặng này có 6 phần. Làm xong mỗi phần, bấm <strong>Tiếp</strong> ở cuối trang.",
      objectives: ["Nhận ra các phần của một chương trình C++ và nơi máy bắt đầu chạy",
        "Dùng câu lệnh cout để in chữ ra màn hình, dùng endl để xuống dòng",
        "Sửa chương trình để màn hình khớp với màn hình mong đợi"],
      flow: [
        { label: "Bối cảnh", title: "Màn hình chào khách của quầy trà sữa",
          html: boiCanh("Lễ hội Mùa Xuân sắp mở. Quầy trà sữa của lớp mình có một màn hình nhỏ để chào khách và giới thiệu menu.",
            `<p>Màn hình chỉ hiện đúng những gì <strong>chương trình</strong> yêu cầu. Chương trình là một dãy câu lệnh viết bằng ngôn ngữ lập trình để máy tính thực hiện. Ở khoá học này, lớp mình dùng ngôn ngữ <strong>C++</strong>.</p>
             <p>Ở chặng này, bạn sẽ đọc hai chương trình chào khách và đoán xem màn hình hiện gì. Sau đó bạn chạy để kiểm tra, rồi tự sửa chương trình in menu cho quầy.</p>`) + sauTab("Kiểm chứng") },
        { label: "Đoán rồi chạy", title: "Hai chương trình chào khách", tasks: ["c1-dc1", "c1-dc2"],
          html: huongDanDoan(2), bit: "Đoán trước rồi mới chạy giúp bạn nhớ lâu hơn." },
        { label: "Kiểm chứng", title: "Điều gì làm kết quả xuất ra màn hình khác nhau?", tasks: ["c1-batdau", "c1-endl", "c1-dungsai"],
          code: CHAO_2, focus: [4],
          html: `<p>Khung bên trái là chương trình ở <strong>Lần 2</strong> (có <code>&lt;&lt; endl</code> ở dòng 4). Dựa vào những gì bạn vừa thấy khi chạy từng dòng, trả lời các câu hỏi bên cạnh.</p>` },
        { label: "Ghi nhớ", title: "Cấu trúc chương trình C++ và câu lệnh cout",
          html: ghiVo(["<code>#include &lt;iostream&gt;</code>: khai báo thư viện để dùng được <code>cout</code>.",
                "<code>using namespace std;</code>: cho phép viết <code>cout</code>, <code>endl</code> thay cho <code>std::cout</code>, <code>std::endl</code>.",
                "<code>int main() { … }</code>: máy chạy tuần tự từng câu lệnh trong <code>{ }</code>, từ trên xuống dưới.",
                "<code>cout &lt;&lt; \"chuỗi\" &lt;&lt; endl;</code>: in chuỗi nguyên văn; <code>endl</code> đưa con trỏ xuống dòng mới."])
            + luuY("<code>cout</code> không tự xuống dòng và không tự thêm dấu cách. Mỗi câu lệnh kết thúc bằng dấu <code>;</code>.")
            + chiTiet
            + bang("1. Các phần của một chương trình C++", ["Dòng lệnh", "Ý nghĩa"], [
              ["<code>#include &lt;iostream&gt;</code>", "Khai báo thư viện <strong>iostream</strong> (input/output stream, nghĩa là luồng nhập/xuất). Có thư viện này, chương trình mới dùng được <code>cout</code> để in và <code>cin</code> để nhập."],
              ["<code>using namespace std;</code>", "Cho phép viết gọn <code>cout</code>, <code>endl</code> thay vì <code>std::cout</code>, <code>std::endl</code>. Trong khoá học này, dòng này luôn đặt <strong>ngay sau</strong> dòng <code>#include</code>. Thiếu dòng này, máy báo không biết tên <code>cout</code>."],
              ["<code>int main() { … }</code>", "Hàm <strong>main</strong> là nơi chương trình <strong>bắt đầu chạy</strong>. Máy thực hiện lần lượt từng câu lệnh bên trong cặp ngoặc nhọn <code>{ }</code>, từ trên xuống dưới."],
              ["<code>return 0;</code>", "Kết thúc hàm main, báo chương trình đã chạy xong bình thường."]])
            + bang("2. Khái niệm", ["Thuật ngữ", "Định nghĩa", "Ví dụ"], [
              ["Chương trình", "Dãy câu lệnh viết bằng một ngôn ngữ lập trình để máy tính thực hiện.", "Chương trình chào khách ở trên"],
              ["Câu lệnh", "Một yêu cầu để máy làm một việc. Trong C++, mỗi câu lệnh kết thúc bằng dấu chấm phẩy <code>;</code>.", "<code>cout &lt;&lt; \"Xin chao\";</code>"],
              ["Chuỗi", "Dãy ký tự đặt trong cặp dấu ngoặc kép. Máy in nguyên văn phần bên trong, không in dấu ngoặc kép.", "<code>\"Tra sua\"</code>"],
              ["<code>cout</code>", "Câu lệnh xuất dữ liệu ra màn hình. Toán tử <code>&lt;&lt;</code> đưa dữ liệu ra <code>cout</code>.", "<code>cout &lt;&lt; \"Tra dao\";</code>"],
              ["<code>endl</code>", "Viết tắt của <em>end line</em>: đưa con trỏ xuống đầu dòng mới. <code>cout</code> không tự xuống dòng.", "<code>cout &lt;&lt; \"A\" &lt;&lt; endl;</code>"]])
            + bang("3. In một dòng và xuống dòng", ["Câu lệnh", "Màn hình"], [
              ["<code>cout &lt;&lt; \"Tra dao\";</code><br><code>cout &lt;&lt; \"Tra sua\";</code>", "<code>Tra daoTra sua</code> (hai chuỗi dính liền vì không có endl)"],
              ["<code>cout &lt;&lt; \"Tra dao\" &lt;&lt; endl;</code><br><code>cout &lt;&lt; \"Tra sua\";</code>", "<code>Tra dao</code><br><code>Tra sua</code>"]])
            + scratch("say [Chao mung den quay tra sua!]", "Câu lệnh cout giống khối <em>nói</em> trong Scratch: in một câu ra cho người xem.")
            + timThem([["https://www.w3schools.com/cpp/cpp_syntax.asp", "W3Schools · Cấu trúc chương trình"],
                       ["https://www.w3schools.com/cpp/cpp_output.asp", "W3Schools · In ra màn hình"],
                       ["https://www.w3schools.com/cpp/cpp_new_lines.asp", "W3Schools · Xuống dòng"],
                       ["https://www.learncpp.com/cpp-tutorial/statements-and-the-structure-of-a-program/", "LearnCpp · Câu lệnh và cấu trúc chương trình"]]) },
        { label: "Luyện tập", title: "Sửa menu, rồi tự xếp chương trình", tasks: ["c1-sua", "c1-xep"],
          html: `<p>Làm theo <strong>4 bước của lập trình viên</strong>:</p>${bonBuoc}` },
        { label: "Phản tư", title: "Bạn đã chắc đến đâu?", tasks: ["c1-tucham"], stop: true,
          html: `<p>${tuCham}</p>`, bit: "Xong Chặng 1! Dừng lại và nhìn lên bảng." }
      ],
      challenges: [
        { id: "c1-dc1", type: "doanchay", predict: true, icon: "🔮",
          title: "Lần 1 · Hai câu lệnh cout",
          prompt: "Chương trình có hai câu lệnh <code>cout</code> ở dòng 4 và dòng 5, mỗi câu lệnh in một chuỗi.",
          ask: "Theo bạn, màn hình sẽ hiện gì?",
          code: CHAO_1, options: MAN_CHAO, answer: MAN_CHAO[1],
          trace: [
            { l: 3, why: "Máy bắt đầu chạy từ hàm <code>main()</code>. Dòng 1 và dòng 2 chỉ chuẩn bị (khai báo thư viện, cho phép viết gọn), không in gì ra màn hình." },
            { l: 4, out: "Chao mung den quay tra sua!", why: "<code>cout</code> in phần chữ nằm trong dấu ngoặc kép, không in chính dấu ngoặc kép. In xong, con trỏ màn hình đứng ngay sau dấu chấm than, vẫn ở dòng cũ." },
            { l: 5, out: "Moi ban chon mon.", why: "Máy in tiếp chuỗi thứ hai ngay tại vị trí con trỏ. Dòng 4 không yêu cầu xuống dòng, nên hai câu bị dính liền và không có dấu cách ở giữa." },
            { l: 6, why: "<code>return 0;</code> kết thúc chương trình." }],
          whyRight: "Câu lệnh cout không tự xuống dòng và không tự thêm dấu cách, nên hai chuỗi in dính liền nhau.",
          why: "Câu lệnh cout không tự xuống dòng và cũng không tự thêm dấu cách. Máy chỉ in đúng những ký tự nằm trong dấu ngoặc kép, nên hai chuỗi dính liền nhau." },
        { id: "c1-dc2", type: "doanchay", predict: true, icon: "🔮", after: "c1-dc1",
          title: "Lần 2 · Thêm endl",
          prompt: "Chương trình này giống Lần 1, chỉ thêm <code>&lt;&lt; endl</code> ở cuối dòng 4.",
          ask: "Theo bạn, lần này màn hình sẽ hiện gì?",
          code: CHAO_2, focus: [4], options: MAN_CHAO, answer: MAN_CHAO[0],
          trace: [
            { l: 3, why: "Máy bắt đầu chạy từ hàm <code>main()</code>." },
            { l: 4, out: "Chao mung den quay tra sua!\n", why: "Máy in chuỗi trong dấu ngoặc kép, rồi gặp <code>endl</code> nên đưa con trỏ xuống đầu dòng mới." },
            { l: 5, out: "Moi ban chon mon.", why: "Chuỗi thứ hai được in ở dòng mới, vì con trỏ đã xuống dòng sau dòng 4." },
            { l: 6, why: "<code>return 0;</code> kết thúc chương trình." }],
          whyRight: "endl ở dòng 4 đưa con trỏ xuống dòng mới, nên câu thứ hai nằm ở dòng dưới.",
          why: "endl ở cuối dòng 4 đưa con trỏ xuống đầu dòng mới, nên chuỗi ở dòng 5 được in ở dòng dưới. endl không in ra chữ nào." },
        { id: "c1-batdau", type: "choice", icon: "👆", title: "Câu lệnh đầu tiên được thực hiện",
          prompt: "Khi bấm chạy chương trình bên trái, máy thực hiện câu lệnh ở dòng nào <strong>đầu tiên</strong>? Nhìn số dòng ở khung code.",
          options: [
            { text: "Dòng 1", why: "Dòng 1 (#include <iostream>) khai báo thư viện để chương trình dùng được cout. Đây là phần chuẩn bị, không phải câu lệnh máy thực hiện trong main()." },
            { text: "Dòng 2", why: "Dòng 2 (using namespace std;) cho phép viết gọn cout thay vì std::cout. Đây cũng là phần chuẩn bị." },
            { text: "Dòng 3", why: "Dòng 3 mở hàm main(). Câu lệnh đầu tiên máy thực hiện là câu lệnh đầu tiên nằm bên trong cặp ngoặc { } của main()." },
            { text: "Dòng 4" }
          ],
          answer: "Dòng 4",
          why: "Đúng. Máy vào hàm main() rồi thực hiện lần lượt từ câu lệnh đầu tiên bên trong cặp ngoặc { }." },
